(() => {
'use strict';
const D = window.PSC_DATA, app = document.getElementById('app'), sheet = document.getElementById('sheet');
const KEY = 'psc-precheck-v2';
const fresh = () => ({version:2, port:'중국 칭다오',arrival:'2026-11-05',language:'idn',generated:false,dispatched:false,onboard:false,offline:true,answers:{},received:{},photos:{},notes:{},queue:[],correctionQueue:[],lastSync:'3h ago',rankChanges:{},rankChangedCount:0,rejected:false,retaken:false,ordered:false,analyzed:false,evidenceRequested:false,corrections:{},approved:{},othersReceived:false,report:false,shared:false,reportLang:'en',owners:{},log:[],visited:[],storageError:false});
function restore(){try{const v=JSON.parse(localStorage.getItem(KEY)||'null');return v?.version===2?{...fresh(),...v}:fresh();}catch{return fresh();}}
let S=restore(), scene=1, view='office', filter='전체', search='', crewIndex=0, loading='', reportRows=0, dashboardTab='선대', auditPage=1, modalTrigger=null, toastTimer, missingExample=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={ship:'M3 17l3 4h12l3-4-9-4-9 4zM6 15V7h12v8M9 7V3h6v4M12 13v8',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',check:'M5 12l4 4L19 6',arrow:'M5 12h14M13 6l6 6-6 6',left:'M15 6l-6 6 6 6',chevron:'M9 5l7 7-7 7',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3zM8 12l3 3 5-5',file:'M14 2H5v20h14V7l-5-5zM14 2v6h5M8 12h8M8 16h8',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',help:'M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',wifi:'M3 8a15 15 0 0 1 18 0M6 12a10 10 0 0 1 12 0M9 16a5 5 0 0 1 6 0M12 20h.01',offline:'M2 2l20 20M3 8a15 15 0 0 1 6-3M13 5a15 15 0 0 1 8 3M6 12a10 10 0 0 1 3-1M15 11a10 10 0 0 1 3 1M9 16a5 5 0 0 1 6 0M12 20h.01',camera:'M8 5l2-2h4l2 2h5v15H3V5h5zM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',upload:'M12 16V4M7 9l5-5 5 5M4 16v5h16v-5',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',alert:'M12 3l10 18H2L12 3zM12 9v5M12 17h.01',x:'M6 6l12 12M6 18L18 6',refresh:'M20 7V2l-4 4a8 8 0 1 0 4 10M20 2v5h-5',person:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 21v-3a8 8 0 0 1 16 0v3',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18',anchor:'M12 6v15M5 10H2a10 10 0 0 0 20 0h-3M15 4a3 3 0 1 1-6 0 3 3 0 0 1 6 0',send:'M22 2L9 15M22 2l-7 20-6-7-7-6 20-7',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',print:'M6 9V2h12v7M6 18H3V9h18v9h-3M6 14h12v8H6z',list:'M9 5h12M9 12h12M9 19h12M3 5h.01M3 12h.01M3 19h.01'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.ship).split(/(?=M)/).map(p=>`<path d="${p}"/>`).join('')}</svg>`;
const btn=(label,action,style='',extra='')=>`<button type="button" class="btn ${style}" data-action="${action}" ${extra}>${label}</button>`;
const tag=(label,type='')=>`<span class="tag ${type}">${label}</span>`;
const notice=(text,type='neutral',i='info')=>`<div class="notice ${type}">${icon(i)}<div>${text}</div></div>`;
const item=id=>D.items.find(x=>x.id===id);
const crew=()=>D.crewIds.map(item);
const isCic=()=>S.arrival>=D.cic.start&&S.arrival<=D.cic.end;
const activeItems=()=>D.items.filter(x=>!x.cic||isCic());
const rate=()=>S.port.startsWith('일본')?D.ports['일본'].value:D.ports['중국'].value;
function ranked(){return activeItems().map(x=>({...x,score:(D.categories[x.category].share*1.3)+(x.top?8+x.top/10*rate()/6.96:0)+(x.previous?12:0)+(x.cic?18:0)})).sort((a,b)=>b.score-a.score||b.top-a.top);}
function owner(x){return S.owners[x.id]??(D.crewIds.includes(x.id)?'기관장':x.owner==='기관장'?'1항사':x.owner);}
function stats(){const all=activeItems();const answered=all.filter(x=>S.received[x.id]).length;const missing=all.length-answered;const open=all.filter(x=>S.received[x.id]==='no'&&!S.approved[x.id]).length;const approved=all.filter(x=>S.approved[x.id]).length;const unassigned=all.filter(x=>!owner(x)).length;return{total:all.length,answered,missing,open,approved,unassigned,percent:Math.round((answered-open)/all.length*100)};}
const due=()=>{const d=new Date(S.arrival+'T12:00:00Z');d.setUTCDate(d.getUTCDate()-2);return d.toISOString().slice(0,10);};
const serviceDate=()=>['2026-10-26','2026-10-29','2026-11-01','2026-11-01','2026-11-03'][Math.min(scene,5)-1];
const dday=()=>{const days=Math.round((Date.parse(S.arrival)-Date.parse(serviceDate()))/86400000);return days<0?`입항 ${-days}일 경과`:days===0?'D-DAY':`D-${days}`;};
function save(){try{localStorage.setItem(KEY,JSON.stringify(S));S.storageError=false;return true;}catch{S.storageError=true;toast('기기 저장 공간이 부족합니다. 기록을 CSV로 내보내 주세요.');return false;}}
function log(text){S.log.unshift({date:serviceDate(),text});S.log=S.log.slice(0,200);}
function toast(text){const el=document.getElementById('toast');clearTimeout(toastTimer);el.textContent=text;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),2500);}
function invalidate(){S.report=false;S.shared=false;}
const equipmentImage=id=>id==='generator'?'img/generator.jpg':'img/fire-pump.jpg';
function photo(id){S.photos[id]={src:equipmentImage(id),kind:id==='generator'?'power':'pump',compressed:true};}
function fastAnswers(){crew().forEach((x,i)=>{S.answers[x.id]=D.faultIds.includes(x.id)?'no':'yes';if([0,1,4].includes(i))photo(x.id);if(!S.queue.includes(x.id))S.queue.push(x.id);});invalidate();}
function sync(){if(S.offline)return;const count=S.queue.length,corrected=S.correctionQueue.length;S.queue.forEach(id=>S.received[id]=S.answers[id]);S.queue=[];S.correctionQueue.forEach(id=>{S.corrections[id]=true;if(id==='fire-pump')S.retaken=true;});S.correctionQueue=[];S.lastSync='just now';log(`기관부 답변 ${count}건 · 시정 ${corrected}건 수신`);save();}
function seed(n){if(S.visited.includes(n))return;let loaded=false;if(n>1&&!S.dispatched){S.generated=true;S.dispatched=true;loaded=true;}if(n===2&&!Object.keys(S.answers).length&&!Object.keys(S.received).length){crew().slice(0,3).forEach((x,i)=>{S.answers[x.id]=D.faultIds.includes(x.id)?'no':'yes';S.queue.push(x.id);if(i<2)photo(x.id);});S.offline=true;loaded=true;}if(n>2&&!Object.keys(S.received).length){fastAnswers();S.offline=false;sync();loaded=true;}if(n>3&&!S.ordered){S.ordered=true;S.rejected=true;loaded=true;}if(n>4&&!S.analyzed){S.analyzed=true;S.evidenceRequested=true;loaded=true;}if(n>4&&!S.othersReceived){receiveOthers(true);loaded=true;}S.visited.push(n);save();if(loaded)setTimeout(()=>toast('이전 장면의 준비된 기록을 불러왔습니다.'),150);}
function receiveOthers(leaveTwo=false){const others=activeItems().filter(x=>!D.crewIds.includes(x.id));others.forEach((x,i)=>{if(!leaveTwo||i<others.length-2)S.received[x.id]='yes';});S.othersReceived=!leaveTwo;invalidate();}
function navigate(n){location.hash=n===6?'done':`scene-${n}`;}
function route(){const m=location.hash.match(/^#scene-([1-5])$/);scene=location.hash==='#done'?6:m?Number(m[1]):1;if(!m&&location.hash!=='#done')history.replaceState(null,'','#scene-1');missingExample=false;seed(scene);view=scene===2?'crew':'office';crewIndex=0;filter='전체';search='';render();window.scrollTo(0,0);}
const progress=(value,green=false)=>`<div class="progress ${green?'green':''}" role="progressbar" aria-label="Inspection completion" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="100"><i style="--value:${value}%"></i></div>`;
const isFull=()=>location.pathname.endsWith('full.html');
function guide(){if(isFull())return `<div class="guide"><span class="guide-step">시연 · 전체 대시보드</span><span class="guide-task">${S.storageError?'기기 저장 불가 · 현재 탭에서만 유지됩니다.':'장면형 시연과 같은 브라우저 저장 기록을 사용합니다.'}</span><a class="btn small" href="index.html${location.hash}">장면으로 돌아가기</a></div>`;if(scene===6)return `<div class="guide"><span class="guide-step">시연 · 5장면 완료</span><span class="guide-task">항차 등록부터 선장 보고서까지 한 사이클을 마쳤습니다.</span>${btn('처음부터','reset','small')}</div>`;const s=D.scenes[scene-1];return `<div class="guide"><span class="guide-step">시연 <span aria-hidden="true">/</span> 장면 ${scene}/5</span><div class="guide-progress" aria-hidden="true">${D.scenes.map((_,i)=>`<i class="${i<scene?'on':''}"></i>`).join('')}</div><span class="guide-task">지금 할 일: ${s.task}</span>${scene===1&&S.generated?btn('예외 보기: 기항지 바꾸기','voyage','guide-fast'):''}${scene===2?btn('빠르게 채우기','fast','guide-fast'):''}${(scene===2||scene>=3&&view==='crew')?btn(S.offline?'연결':'오프라인 전환','connection','guide-fast'):''}${scene===5?btn(missingExample?'예외 닫기':'예외 보기: 미응답','exception-missing','guide-fast'):''}<button data-action="next">${scene===5?'마치기':'다음'} ${icon('arrow')}</button></div>`;}
function topbar(){return `<header class="appbar"><div class="brand"><span class="brand-icon">${icon('ship')}</span>PSC 프리체크</div><span class="appbar-sub">입항 전, 준비의 기준</span><div class="grow"></div><span class="header-label small muted">${serviceDate()} · ${dday()}</span><button class="iconbtn" aria-label="알림" data-action="notifications">${icon('bell')}${S.ordered?'<span class="badge-number">2</span>':''}</button><span class="avatar" aria-hidden="true">김</span><span class="user-name small">김 과장 <span class="muted">· DPA</span></span></header>`;}
function tabs(cls){return `<div class="${cls}" role="group" aria-label="역할 전환">${[['office','사무실'],['crew','선원 폰'],['captain','선장']].map(([id,t])=>`<button data-action="view" data-value="${id}" class="${view===id?'active':''}" aria-pressed="${view===id}">${t}</button>`).join('')}</div>`;}
function render(){const full=isFull();app.innerHTML=guide()+topbar()+tabs('mobile-tabs')+`<div class="shell"><nav class="rail" aria-label="주 메뉴">${[['grid','선대',1],['list','점검',2],['file','증빙',4],['shield','보고서',5]].map(([i,t,n])=>`<button data-action="nav" data-value="${n}" class="${scene===n?'active':''}">${icon(i)}${t}</button>`).join('')}<button class="rail-bottom" data-action="help">${icon('help')}도움말</button></nav><main id="main" class="workspace show-${view} scene-${scene}" tabindex="-1"><div class="work-top"><div class="breadcrumb">WORKSPACE <span>/</span> 운항 안전 <span>/</span> <strong>${scene===1?'선대 현황':D.scenes[Math.min(scene,5)-1].title}</strong></div>${tabs('view-tabs')}</div>${scene===6?done():`<div class="columns"><section class="office animation-in" aria-label="사무실 화면">${full?fullNav():''}${office()}</section><aside class="phone-wrap" aria-label="선내 화면"><div class="phone-label"><span>${view==='captain'?'MASTER · 선장':'ON BOARD · 선원'}</span><span class="row gap2">${icon('wifi')} 선내 연결</span></div><div class="phone"><div class="phone-status"><span>09:41</span><span>${icon('wifi')} ▰</span></div><header class="phone-head"><div><strong>${view==='captain'?'한바다스타':'HANBADA STAR'}</strong><div class="small muted">${view==='captain'?'선장 · 입항 준비 현황':'Budi · Chief Engineer'}</div></div><div class="phone-tools">${tag(dday(),'navy')}${view==='captain'?'':languageSelect()}</div></header><div class="phone-body" id="crew-panel">${view==='captain'?captain():languageNotice()+crewPanel()}</div><nav class="phone-nav" aria-label="Onboard navigation"><button class="${view!=='captain'?'active':''}" data-action="view" data-value="crew">${icon('list')}${tr('Tugas','Tasks')}</button><button data-action="phone-notices">${icon('bell')}${tr('Notifikasi','Notifications')}</button><button class="${view==='captain'?'active':''}" data-action="view" data-value="captain">${icon('person')}${view==='captain'?'선장':tr('Nakhoda','Master')}</button></nav></div>${story()}</aside></div>`}<footer class="app-footer"><span>시연용 모의 데이터 · 선박·IMO·인물 가상 · 통계 출처 Tokyo MOU</span><span><button data-action="sources">출처</button> · <button data-action="help">도움말·개인정보</button></span></footer></main></div>`;}
function story(){if(scene>5)return'';const s=D.scenes[scene-1];return `<div class="story-panel"><div class="story-title">${icon('info')} 시연 가이드 · ${String(scene).padStart(2,'0')}</div><div><strong>이야기</strong>${s.story}</div><div><strong>성공 확인</strong>${s.success}</div></div>`;}
function office(){if(loading==='generate')return `<div class="section-head"><h1>점검 항목을 정리하고 있어요</h1><p>공개 통계 · 지난 지적 · 집중점검 기간 확인 중</p></div><div role="status" aria-label="체크리스트 생성 중">${[1,2,3].map(()=>'<div class="skeleton"></div>').join('')}</div>`;if(isFull()&&dashboardTab==='기록')return audit();if(isFull()&&dashboardTab==='전체 점검')return checklist(true);switch(scene){case 1:return S.generated?checklist():fleet();case 2:return syncOffice();case 3:return review();case 4:return analysis();case 5:return S.report&&!missingExample?reportPage():completion();default:return fleet();}}
function heading(title,sub,action=''){return `<div class="section-head"><div class="row between"><h1>${title}</h1>${action}</div><p>${sub}</p></div>`;}
function fleet(){return heading('선대 현황','오늘의 입항 준비를 한눈에 확인하세요.',tag('3척 운항 중','navy'))+`<article class="fleet-hero"><div class="row between"><span class="eyebrow">NEXT PORT CALL</span><span class="tag">${icon('clock')} ${dday()} · 항차 등록 필요</span></div><div class="row between" style="margin-top:var(--s4)"><div><h2>한바다스타</h2><div class="muted small">IMO 9000001 · Bulk carrier · 35,000 GT</div></div>${icon('ship')}</div><div class="hero-route"><div><div class="small muted">출항지</div><span class="port-name">부산</span></div><div class="route-line">${icon('ship')}</div><div class="text-right"><div class="small muted">다음 기항지</div><span class="port-name">칭다오</span></div></div><div class="hero-bottom"><div><strong>11월 5일 입항 예정</strong><br><small class="muted">지난 지적 3건 · 준비 시작 전</small></div>${btn('다음 항차 등록 '+icon('arrow'),'voyage')}</div></article><div class="fleet-cards">${D.ships.slice(1).map((x,i)=>`<button class="card ship-small" data-action="ship-detail" data-value="${i+1}"><div class="row between">${icon('ship')}${tag(i?'준비 완료':'점검 중',i?'ok':'navy')}</div><h3>${x.name}</h3><p class="muted small">${x.imo} · ${i?'11.20':'11.12'} 입항</p><div class="row between mt"><span class="metric">${i?100:83}<small>%</small></span><span class="small muted">${i?'미비 없음':'검토 대기 1건'}</span></div>${progress(i?100:83,i===1)}</button>`).join('')}</div><section class="card mt"><div class="row between"><h3>지금 확인할 일</h3><span class="small muted">2건</span></div><div class="task-row"><span class="task-icon">${icon('file')}</span><div class="grow"><strong>지난 PSC 지적, 증빙을 확인하세요</strong><p>한바다스타 · 6월 2일 부산 · 결함 3건</p></div><button class="iconbtn" aria-label="지난 보고서 확인" data-action="nav" data-value="4">${icon('chevron')}</button></div><div class="task-row"><span class="task-icon">${icon('shield')}</span><div class="grow"><strong>11월은 화물 고박 집중점검 기간</strong><p>입항일에 맞춰 점검 항목이 추가됩니다.</p></div></div></section>`;}
function checklist(all=false){const r=ranked(),rows=all?r:r.slice(0,12);return heading('한바다스타 · 입항 준비',`${esc(S.port)} · ${S.arrival} 입항 · ${dday()}`,btn(icon('refresh')+' 항차 변경','voyage','small'))+`<section class="card risk-card"><div><span class="eyebrow muted">SHIP RISK PROFILE</span><h2 style="margin-top:var(--s2)">표준 위험 선박</h2><p class="muted small">입항일 ${S.arrival>='2026-11-02'&&S.arrival<='2027-02-02'?'점검 가능 기간 안':'점검 창 밖'} · 최근 검사 후 5~8개월</p></div><div class="risk-points">3<small>NIR 가중점</small></div><details><summary>${icon('info')} 위험도 산출 근거</summary>벌크선 2 + 선령 14년 1 = 3점. 대한민국 기국 High, 선급·회사 성능은 Low 아님, 36개월 내 결함 5건 초과 점검 없음·억류 없음으로 설정한 가상 선박입니다. 4점 이상은 고위험. 선급: 미입력.</details><div class="timeline" style="grid-column:1/-1"><div><b>06.02</b><span>지난 PSC</span></div><div><b>11.02</b><span>점검 창 열림</span></div><div class="arrival"><b>${S.arrival.slice(5).replace('-','.')}</b><span>입항 예정</span></div></div></section><div class="mt">${isCic()?notice('<strong>화물 고박 집중점검 · CIC 2026</strong><p>09.01–11.30 · 10문항 추가 (1a·1b 포함 11개 세부 항목)</p>','warn','shield'):notice('집중점검 기간 밖입니다. CIC 항목을 제외했습니다.','neutral')}</div><div class="list-header"><h3>${all?'전체 체크리스트':'먼저 확인할 12항목'}</h3><button class="btn ghost small" data-action="ranking-info">순위 기준 ${icon('info')}</button></div><p class="muted small mb">공개 통계와 이 배의 이력으로 매긴 점검 순서</p>${S.rankChangedCount?`<p id="rank-update" class="rank-update">${icon('refresh')} 순위가 바뀐 항목 ${S.rankChangedCount}개 · ▲▼ 직전 항차 대비</p>`:''}<div class="rank-list">${rows.map((x,i)=>rankRow(x,i)).join('')}</div><div class="sticky-actions">${btn(icon('download')+' CSV','csv')}${btn(S.dispatched?icon('check')+' 배정 완료 · 다시 보내기':icon('send')+' 배로 보내기','dispatch','primary')}</div><p class="small muted">기관부 우선 점검 6 · 갑판부 4 · 선장 2 항목 배정. 전체 ${activeItems().length}항목은 전체 보기에서 확인합니다.</p>`;}
function rankRow(x,i){const delta=S.rankChanges?.[x.id]||0;return `<div class="rank-row"><span class="rank-number">${String(i+1).padStart(2,'0')}${delta?`<span class="rank-change" aria-label="${Math.abs(delta)}단계 ${delta>0?'상승':'하락'}">${delta>0?'▲':'▼'}${Math.abs(delta)}</span>`:''}</span><button class="rank-evidence grow" data-action="evidence" data-value="${x.id}" aria-label="${esc(x.ko)} 근거와 출처"><span class="rank-title"><strong>${esc(x.ko)}</strong><span class="rank-en">${esc(x.en)}</span></span><span class="evidence-chips">${x.top?tag(`억류 다발 · ${x.top}건`):tag(x.cic?`CIC ${x.question}`:`범주 결함 ${D.categories[x.category].share}%`)}${x.previous?tag('지난 점검 지적'):''}<span class="evidence-link">${icon('info')} 출처</span></span></button><button class="btn ghost small" data-action="assign" data-value="${x.id}" aria-label="${esc(x.ko)} 담당 배정">${tag(owner(x)||'미지정',owner(x)?'':'warn')}</button></div>`;}
function syncOffice(){const s=stats();return heading('선내 점검 현황','한바다스타 · 기관부 답변을 기다리고 있습니다.',tag(dday(),'navy'))+`<div class="card"><div class="row between"><div><span class="muted small">확인된 점검</span><div class="metric" id="office-progress">${s.answered}<span class="muted" style="font-size:var(--f20)"> / ${s.total}</span></div></div>${tag(S.queue.length?'전송 대기':'수신 상태',S.queue.length?'warn':'navy')}</div><div class="mt">${progress(Math.round(s.answered/s.total*100))}</div><div class="summary-grid"><div><b class="metric">${s.answered}</b><span>답변 수신</span></div><div><b class="metric">${s.open}</b><span>미비 항목</span></div><div><b class="metric">${s.missing}</b><span>미응답</span></div></div>${notice(S.offline?'선박이 오프라인입니다. 선내 저장된 답변은 연결 후 도착합니다.':'선박 연결됨 · 마지막 동기화 '+S.lastSync,S.offline?'neutral':'ok',S.offline?'offline':'check')}</div><div class="list-header"><h3>수신한 기관부 답변</h3>${tag(`${Object.keys(S.received).filter(id=>D.crewIds.includes(id)).length} / 6`)}</div>${!Object.keys(S.received).length?`<div class="card empty">${icon('wifi')}<h3>아직 도착한 답변이 없어요</h3><p>선원은 통신이 없어도 점검을 계속할 수 있습니다.<br>연결되면 이곳에 결과가 모입니다.</p></div>`:crew().map(x=>`<div class="task-row"><span class="task-icon">${icon(S.received[x.id]==='no'?'alert':'check')}</span><div class="grow"><strong>${x.ko}</strong><p>기관장 · ${S.photos[x.id]?'사진 첨부':'답변 수신'}</p></div>${tag(S.received[x.id]==='no'?'미비':'이상 없음',S.received[x.id]==='no'?'bad':'ok')}</div>`).join('')}${Object.keys(S.received).length?btn('답변 검토하기 '+icon('arrow'),'nav','primary wide mt','data-value="3"'):''}`;}
function languageSelect(){const code={idn:'ID',en:'EN',vi:'VI',tl:'FIL'}[S.language]||'EN';return `<label class="language-chip" for="crew-language"><span aria-hidden="true">${icon('globe')} ${code}</span><span class="sr-only">Language</span><select id="crew-language" data-change="language" aria-label="Language">${[['idn','Bahasa Indonesia'],['en','English'],['vi','Tiếng Việt'],['tl','Filipino']].map(([v,l])=>`<option value="${v}" ${S.language===v?'selected':''}>${l}</option>`).join('')}</select></label>`;}
function languageNotice(){return ['vi','tl'].includes(S.language)?'<p class="muted small language-note" role="status">Translation pending · Showing English</p>':'';}

const tr=(id,en)=>S.language==='idn'?id:en;
const portEnglish=()=>S.port==='중국 칭다오'?'Qingdao, China':S.port==='중국 르자오'?'Rizhao, China':'Chiba, Japan';
const bilingual=(id,en)=>tr(id,en)+(S.language==='idn'?`<small class="translation">${en}</small>`:'');
function networkStatus(){const photos=S.queue.filter(id=>S.photos[id]).length;return notice(`<strong>${S.offline?'Offline':'Online'}</strong><p>${S.queue.length?tr(`${S.queue.length} jawaban menunggu · ${photos} foto`,`${S.queue.length} answers queued · ${photos} photos`):tr('Semua jawaban terkirim','All answers sent')}</p><small>${tr('Sinkronisasi terakhir','Last sync')}: ${['just now','방금'].includes(S.lastSync)?tr('baru saja','just now'):tr('3 jam lalu','3 hours ago')}</small>`,S.offline?'warn':'ok',S.offline?'offline':'wifi');}
function crewPanel(){if(scene>=5&&S.report)return crewReportReady();if(scene===1&&!S.dispatched)return `<span class="eyebrow muted mt">${tr('SELAMAT DATANG','WELCOME ABOARD')}</span><h2 class="mt">${bilingual('Siap untuk pelabuhan berikutnya.','Get ready for your next port.')}</h2><div class="phone-illustration">${icon('shield')}<p class="mt">${tr('6 tugas','6 tasks')} · Chief Engineer</p></div>${S.onboard?notice(bilingual('Akun kapal aktif. Menunggu daftar tugas.','Vessel account connected. Awaiting assignment.'),'ok','check'):btn(bilingual('Mulai','Get started')+icon('arrow'),'onboard','primary')}<p class="muted mt">${bilingual('Foto peralatan saja, tanpa wajah.','Equipment photos only. No faces.')}</p>`;if(scene>=3)return crewTasks();if(scene===1&&S.dispatched)return `<span class="eyebrow muted mt">${tr('DAFTAR TUGAS DITERIMA','TASK LIST RECEIVED')}</span><h2 class="mt">${bilingual('6 tugas siap diperiksa.','6 inspection tasks received.')}</h2><div class="phone-illustration">${icon('list')}<p class="mt">${portEnglish()} · ${S.arrival}</p></div>${btn(bilingual('Mulai pemeriksaan','Start inspection')+icon('arrow'),'nav','primary','data-value="2"')}<p class="muted mt">${bilingual('Jawaban tersimpan saat offline.','Answers are saved offline.')}</p>`;return crewCheck();}
function crewCheck(){const x=crew()[crewIndex],count=crew().filter(x=>S.answers[x.id]).length,photos=crew().filter(x=>S.photos[x.id]).length;return `${networkStatus()}<div class="row between check-count"><span class="eyebrow muted">${tr('PEMERIKSAAN','INSPECTION')} ${crewIndex+1} / 6</span><span class="small muted">${count}/6 ${tr('tersimpan','saved')}</span></div>${progress(count/6*100)}<div class="question"><h2>${esc(S.language==='idn'?x.idn:x.en)}</h2>${S.language==='idn'?`<p>${x.en}</p>`:''}</div><div class="answers"><button class="btn ${S.answers[x.id]==='yes'?'chosen':''}" data-action="answer" data-value="yes" aria-pressed="${S.answers[x.id]==='yes'}">${icon('check')} ${tr('Ya','Yes')}</button><button class="btn ${S.answers[x.id]==='no'?'chosen':''}" data-action="answer" data-value="no" aria-pressed="${S.answers[x.id]==='no'}">${icon('x')} ${tr('Tidak','No')}</button></div><details class="korean-reference"><summary>한국어 보기 ${icon('chevron')}</summary>${x.ko}</details>${S.photos[x.id]?`<div class="row mb"><img class="thumb ${x.id==='fire-pump'&&!S.retaken?'blurred':''}" src="${equipmentImage(x.id)}" alt="Equipment inspection photo"><span class="muted">${bilingual('Foto tersimpan','Photo saved')}</span><button class="iconbtn" data-action="remove-photo" aria-label="Remove photo">${icon('x')}</button></div>`:btn(icon('camera')+' '+bilingual('Foto','Attach photo'),'photo','wide')}<label for="crew-note" class="sr-only">${tr('Catatan','Note')}</label><input class="mt" id="crew-note" data-change="note" maxlength="180" placeholder="${tr('Catatan singkat','Short note')}" value="${esc(S.notes[x.id]||'')}"><div class="row mt"><button class="iconbtn" data-action="crew-prev" aria-label="Previous item" ${crewIndex===0?'disabled':''}>${icon('left')}</button>${btn(crewIndex===5?bilingual('Selesai','Finish'):bilingual('Berikutnya','Next'),'crew-next','primary grow')}</div>${S.answers[x.id]?btn(bilingual('Batalkan jawaban','Undo answer'),'undo','ghost small'):''}${count===6?notice(S.offline?bilingual(`${S.queue.length} jawaban · ${photos} foto tersimpan. Dikirim saat tersambung.`,`${S.queue.length} answers · ${photos} photos saved. Sends when connected.`):bilingual('Terkirim ✓ Foto 4.1MB → 280KB','Sent ✓ Photo transfer model: 4.1MB → 280KB'),S.offline?'neutral':'ok'):''}`;}
function review(){const s=stats();let rows=crew().filter(x=>filter==='전체'||filter==='아니오'&&S.received[x.id]==='no'||filter==='사진 확인 필요'&&x.id==='fire-pump'||filter==='미응답'&&!S.received[x.id]);if(filter==='미응답')rows=activeItems().filter(x=>!S.received[x.id]);rows.sort((a,b)=>(b.id==='fire-pump'?3:S.received[b.id]==='no'?2:0)-(a.id==='fire-pump'?3:S.received[a.id]==='no'?2:0));rows=rows.filter(x=>(x.ko+x.en+(D.codes[x.id]||'')).toLowerCase().includes(search.toLowerCase()));return heading('입항 전, 미비를 닫아주세요',`${S.port} · 시정 기한 ${due()} · 입항 2일 전`,tag(dday(),'navy'))+`<div class="summary-grid"><div><b class="metric">${s.open}</b><span>시정 필요</span></div><div><b class="metric">${S.retaken?0:1}</b><span>사진 재확인</span></div><div><b class="metric">${s.missing}</b><span>미응답</span></div></div><div class="search">${icon('search')}<input type="search" id="review-search" placeholder="항목·결함 코드 검색" aria-label="항목 검색" value="${esc(search)}"></div><div class="filter-bar">${['전체','아니오','사진 확인 필요','미응답'].map(t=>`<button data-action="filter" data-value="${t}" class="${filter===t?'active':''}">${t}</button>`).join('')}</div><div id="review-results">${rows.length?rows.map(reviewRow).join(''):`<div class="card empty">${icon('search')}<h3>해당 항목이 없어요</h3><p>검색어나 필터를 바꿔 보세요.</p>${btn('필터 초기화','clear-filter','small')}</div>`}</div><div class="sticky-actions">${S.ordered?notice('시정 지시 전달됨 · 11/01 14:20','ok','check'):btn(icon('send')+' 미비 2건 시정 지시','order','primary')}</div>`;}
function reviewRow(x){const no=S.received[x.id]==='no';return `<article class="card review-card"><div class="row between"><span class="small muted">${D.codes[x.id]||x.category} · ${owner(x)||'미지정'}</span>${tag(!S.received[x.id]?'미응답':no?'아니오':'이상 없음',!S.received[x.id]?'':no?'bad':'ok')}</div><h3 style="margin-top:var(--s2)">${x.ko}</h3>${x.id==='fire-pump'?`<div class="review-body"><img class="thumb ${S.retaken?'':'blurred'}" src="img/fire-pump.jpg" alt="압력계 눈금이 흐린 소화펌프 사진"><div class="grow"><strong>${S.retaken?'다시 촬영한 사진 도착':'압력계 숫자를 확인할 수 없어요'}</strong><p class="muted small">${S.retaken?'새 사진을 확인하고 시정을 승인하세요.':'사진 확인 필요 · 기관실 소화펌프'}</p></div></div>${btn(S.rejected?'재촬영 요청 전달됨':'다시 찍어 주세요','reject','small',S.rejected?'disabled':'')}`:no?`<p class="muted small mt">자동 기동 시험 실패 · 기관장 확인 요청</p>`:''}</article>`;}
function crewReportReady(){const approved=stats().approved;return `<section class="phone-card report-ready" aria-labelledby="crew-report-title"><div class="row between"><span class="task-icon">${icon('file')}</span>${tag(tr('SIAP','READY'),'ok')}</div><h2 id="crew-report-title">${bilingual('Laporan siap','Report ready')}</h2><p class="report-number">HB-2026-1105</p><p class="muted">${portEnglish()} · ${S.arrival}</p><div class="report-ready-status">${notice(`<strong>${approved} ${tr('perbaikan','corrections')} · ${tr('Disetujui','Approved')} ✓</strong>`,'ok','check')}${notice(`<strong>1 ${tr('bukti sedang disiapkan','evidence pending')}</strong><p>15150 · ISM</p>`,'warn','file')}</div>${btn(icon('file')+' '+bilingual('Lihat laporan','View report'),'captain-report','wide')}</section>`;}
function crewTasks(){const documents=S.evidenceRequested?`<div class="phone-card document-request"><div class="row between"><span class="eyebrow">15150 · ISM</span>${tag(tr('BARU','NEW'),'navy')}</div><h3 class="mt">${bilingual('Dokumen diperlukan','Documents needed')}</h3><ul><li>${bilingual('Catatan pemeliharaan PMS','PMS maintenance record')}</li><li>${bilingual('Foto pekerjaan','Work photos')}</li><li>${bilingual('Catatan audit internal','Internal audit record')}</li></ul>${tag(tr('Bukti sedang disiapkan','Evidence pending'),'warn')}</div>`:'';return `${scene===4?documents:''}${networkStatus()}${S.rejected&&!S.retaken?notice(`<strong>${bilingual('Foto perlu diambil ulang','Photo retake requested')}</strong><p>${S.rejectReason==='wrong'?bilingual('Foto tidak sesuai dengan peralatan yang diperiksa.','Photo does not match the equipment.'):bilingual('Angka manometer tidak terlihat.','The pressure gauge numbers are not visible.')}</p>`,'warn','camera'):''}<div class="row between mt"><h3>${tr('Tugas perbaikan','Corrective tasks')}</h3>${tag(S.ordered?'2':'0','navy')}</div><p class="muted mt">${tr('Tenggat','Due')}: ${due()}</p>${S.ordered?D.faultIds.map(id=>`<div class="phone-card"><div class="small muted">${id==='fire-pump'?'01':'02'} · Chief Engineer</div><h3 class="mt">${bilingual(item(id).idn,item(id).en)}</h3>${S.corrections[id]?`<img src="${equipmentImage(id)}" alt="Corrected equipment photo"><div class="small muted">${id==='generator'?bilingual('Foto pemeliharaan dan catatan uji mulai otomatis.','Maintenance photo and auto-start test record.'):''}</div>`:''}${S.approved[id]?notice(bilingual('Disetujui · selesai','Approved · complete'),'ok','check'):S.corrections[id]?notice(bilingual('Terkirim · menunggu persetujuan','Sent · awaiting approval'),'neutral','clock'):S.correctionQueue.includes(id)?notice(bilingual('Tersimpan · menunggu koneksi','Saved · waiting for connection'),'neutral','offline'):btn(icon('camera')+' '+bilingual('Sudah diperbaiki + foto','Fixed + photo'),'correct','primary mt',`data-value="${id}"`)}</div>`).join(''):`<div class="empty">${icon('check')}<p>${bilingual('Belum ada tugas perbaikan.','No corrective tasks yet.')}</p></div>`}${scene!==4?documents:''}${S.shared?btn(icon('file')+' '+bilingual('Lihat laporan','View report'),'view','wide mt','data-value="captain"'):''}`;}
function analysis(){return heading('지난 지적을 놓치지 않도록','2026.06.02 부산 · Tokyo MOU Form B',tag('결함 3건','navy'))+(!S.analyzed&&loading!=='analysis'?`<div class="upload" id="dropzone">${icon('upload')}<h2>지난 PSC 보고서</h2><p>PDF를 끌어 놓거나 준비된 보고서를 불러오세요.</p>${btn(icon('file')+' 6월 부산항 보고서 불러오기','analyze','primary')}<label class="btn ghost small mt" for="report-upload">다른 PDF 선택</label><input class="sr-only" type="file" id="report-upload" accept="application/pdf,.pdf"></div><section class="card mt"><div class="row gap2">${icon('shield')}<h3>지난 시정의 근거까지 한곳에</h3></div><p class="muted mt">결함 코드, 조치 기한, 시정 사진과 정비 기록을 연결합니다. 기록이 없으면 없다고 표시합니다.</p></section>`:`<div class="report-grid"><section class="document"><header><span class="eyebrow muted">ORIGINAL DOCUMENT</span><h2 class="mt">PORT STATE CONTROL</h2><p class="small muted">FORM B · Report of inspection</p></header><div class="small">HANBADA STAR · IMO 9000001<br>Busan, Republic of Korea · 02 JUN 2026<br>No detention</div><div class="form-row"><b>Code</b><b>Nature of deficiency</b><b>Act.</b></div>${D.report.map(r=>`<div class="form-row"><span>${r.code}</span><span>${r.en}</span><b>${r.action}</b></div>`).join('')}<p class="small muted mt">Action 17 · Rectify before departure<br>Action 16 · Rectify within 14 days<br>Action 30 · Detainable deficiency</p></section><section><div class="list-header" style="margin-top:0"><h3>읽은 결과</h3>${tag(`${S.analyzed?3:reportRows} / 3`)}</div>${D.report.slice(0,S.analyzed?3:reportRows).map((r,i)=>`<div class="report-result ${i===2?'bad':''} mb animation-in"><div class="row between"><strong>${r.code}</strong>${tag(i===2?'증빙 없음':'증빙 확인',i===2?'bad':'ok')}</div><h3 style="margin-top:var(--s2)">${['방화문 닫힘 상태','구명정','ISM 선박·설비 정비'][i]}</h3><p class="small muted">조치 ${r.action} · ${r.action===17?'출항 전 시정':'2026-06-16 기한'}</p><p class="small mt">${r.evidence}</p></div>`).join('')}${loading==='analysis'?'<div class="skeleton" role="status" aria-label="보고서 읽는 중"></div>':''}</section></div><div class="mt">${notice('<strong>15150 · 정비기록의 시정 증빙이 없습니다.</strong><p>PMS 정비기록 출력 · 작업 사진 · 내부심사 기록이 필요합니다.</p>','bad','alert')}</div><div class="sticky-actions">${S.evidenceRequested?notice('증빙 요청 전달됨 · 11/01 14:20','ok','check'):btn(icon('send')+' 증빙 묶음에 요청 추가','request-evidence','primary',!S.analyzed?'disabled':'')}</div>`)+`<p class="muted small mt">이 파일은 사전 구조화된 결과를 불러옵니다. 실제 서비스의 AI PDF 분석은 연결 전이며 다른 PDF를 자동 판독하지 않습니다.</p>`;}
function blockers(){const s=stats();if(missingExample)return ['미응답 2항목'];return[s.missing?`미응답 ${s.missing}항목`:'',s.unassigned?`담당자 미지정 ${s.unassigned}항목`:'',s.open?`시정 승인 대기 ${s.open}건`:'',S.rejected&&!S.retaken?'재촬영 사진 미도착':'',S.queue.length||S.correctionQueue.length?'오프라인 전송 대기':''].filter(Boolean);}
function completion(){if(missingExample)return heading('아직 발행할 수 없어요','한바다스타 · '+S.arrival+' 입항',tag('미응답 2','warn'))+`<section class="card"><span class="eyebrow muted">PORT READINESS</span><h2 class="mt">답변 2건을 기다리고 있습니다.</h2><p class="muted mt">담당자의 점검 답변이 모두 도착해야 보고서를 발행할 수 있습니다.</p><div class="summary-grid"><div><b class="metric">${activeItems().length-2}</b><span>답변 수신</span></div><div><b class="metric">2</b><span>미응답</span></div><div><b class="metric">${activeItems().length}</b><span>전체 점검</span></div></div>${notice('미응답 2항목 · 갑판부 점검 답변 대기','warn','clock')}<div class="sticky-actions">${btn(icon('file')+' 입항 준비 보고서 발행','issue','primary','disabled aria-describedby="issue-reason"')}</div><p id="issue-reason" class="small muted">미응답 2항목 — 답변 수신 후 발행할 수 있습니다.</p></section>`;const s=stats(),blocks=blockers();if(missingExample){s.missing=2;s.answered=s.total-2;s.percent=Math.round(s.answered/s.total*100);}return heading('준비의 마지막 한 단계',`${S.port} · ${S.arrival} 입항 · 시정 기한 ${due()}`,tag(dday(),'navy'))+`<p class="arrival-history">D-4 · 미응답 ${activeItems().length-6} → D-3 · ${activeItems().length-8}항목 추가 수신 → D-2 · ${s.missing?'마지막 '+s.missing+'항목 확인 중':'전체 답변 완료'}</p><section class="card"><div class="row between"><div><span class="eyebrow muted">PORT READINESS</span><div class="metric" style="font-size:var(--f36)">${s.percent}% <span class="small muted">확인 완료</span></div></div><span class="task-icon">${icon('shield')}</span></div><div class="mt">${progress(s.percent,s.percent===100)}</div><div class="row between mt small"><span>점검 ${s.answered}/${s.total}</span><span>시정 승인 ${s.approved}/2</span><span>미응답 ${s.missing}</span></div></section><div class="list-header"><h3>시정 결과 검토</h3><span class="small muted">기관장 → DPA</span></div>${D.faultIds.map(id=>`<article class="card review-card"><div class="row between"><h3>${item(id).ko}</h3>${tag(S.approved[id]?'승인 완료':S.corrections[id]?'승인 대기':'사진 대기',S.approved[id]?'ok':'warn')}</div>${S.corrections[id]?`<div class="review-body"><img class="thumb" src="${equipmentImage(id)}" alt="시정 후 설비 사진 참고"><div class="grow"><strong>${id==='fire-pump'?'압력계 재촬영 · 시험 완료':'자동 기동 시험 완료'}</strong><p class="muted small">${due()} · Chief Engineer<br>${id==='generator'?'설비 사진 참고 + 기동 시험 기록':'새 사진 280KB · 눈금 확인 가능'}</p></div></div>`:`<p class="muted small mt">선원의 시정 사진을 기다리고 있습니다.</p>`}${btn(S.approved[id]?icon('check')+' 승인됨':'시정 승인','approve',S.approved[id]?'small':'primary small mt',`data-value="${id}" ${!S.corrections[id]||S.approved[id]?'disabled':''}`)}</article>`).join('')}${s.missing&&!missingExample?`<div class="card mt"><h3>미응답 ${s.missing}항목이 남아 있어요</h3><p class="muted small mt">갑판부·선장의 점검 답변을 수신해야 발행할 수 있습니다.</p>${btn(icon('refresh')+' 나머지 점검 답변 수신','receive-others','wide mt')}</div>`:''}${S.analyzed?`<div class="mt">${notice('지난 지적 15150 · ISM 정비 증빙 준비 중<br>보고서에 미완료 상태를 그대로 남깁니다.','warn','file')}</div>`:''}<div class="sticky-actions">${btn(icon('file')+' 입항 준비 보고서 발행','issue','primary',blocks.length?'disabled aria-describedby="issue-reason"':'')}</div><p id="issue-reason" class="small ${blocks.length?'muted':''}">${blocks.length?blocks.join(' · ')+' — 완료 후 발행할 수 있습니다.':'모든 점검·시정 확인 완료. 보고서를 발행할 수 있습니다.'}</p>`;}
function reportContent(){const en=S.reportLang==='en',s=stats();return `<article class="report-paper" id="port-report" lang="${en?'en':'ko'}"><header class="report-top"><div class="row between"><span class="eyebrow">PSC PRECHECK</span><span>HB-2026-1105 · REV 01</span></div><h1>${en?'Port Readiness Report':'입항 준비 보고서'}</h1><p class="muted">${en?'Inspection preparation & corrective action summary':'점검 준비 및 시정 조치 요약'}</p></header><div class="report-meta"><div><span>${en?'Vessel / IMO':'선박 / IMO'}</span><b>HANBADA STAR · 9000001</b></div><div><span>${en?'Arrival / Port':'입항일 / 기항지'}</span><b>${S.arrival} · ${S.port==='중국 칭다오'?'Qingdao':S.port==='중국 르자오'?'Rizhao':'Chiba'}</b></div><div><span>${en?'Type / Flag / Built':'선종 / 기국 / 건조'}</span>Bulk carrier · Korea · 2012</div><div><span>${en?'Gross tonnage / Risk':'총톤수 / 위험도'}</span>35,000 GT · SRS (3 points)</div></div><div class="report-stats"><div><b>${s.answered}/${s.total}</b>${en?'Checked':'점검 완료'}</div><div><b>${s.answered-s.approved}</b>${en?'Satisfactory':'이상 없음'}</div><div><b>${s.approved}</b>${en?'Corrected':'시정 완료'}</div></div><h2>01 / ${en?'Inspection window & campaign':'점검 창과 집중점검'}</h2><p>SRS window: 02 NOV 2026 – 02 FEB 2027.<br>${isCic()?'CIC 2026 · Cargo securing · 10 questions (11 sub-items).':en?'CIC not active on arrival date.':'입항일 기준 CIC 기간 외.'}</p><h2>02 / ${en?'Previous PSC findings · Busan, 02 JUN 2026':'지난 PSC 지적 · 2026.06.02 부산'}</h2>${D.report.map((r,i)=>`<div class="report-evidence"><div class="row between"><strong>${r.code} · ${en?r.en:['방화문','구명정','ISM 정비기록'][i]}</strong><b>${i===2?(en?'PENDING':'준비 중'):(en?'VERIFIED':'확인 완료')}</b></div><span class="muted">Action ${r.action} · ${i===2?(en?'PMS record, work photos and internal audit record requested.':'PMS 정비기록·작업 사진·내부심사 기록 요청.'):(en?'Corrective evidence attached.':'시정 증빙 첨부.')}</span></div>`).join('')}<h2>03 / ${en?'Corrective evidence':'시정 증빙'}</h2><div class="row"><img class="report-photo" src="img/fire-pump.jpg" alt="시정 설비 압력계 참고 이미지"><img class="report-photo" src="img/generator.jpg" alt="비상발전기 시정 증빙 참고 이미지"></div><p class="small" style="margin-top:var(--s2)">Fire pump pressure test · Emergency generator auto-start<br><span class="muted">${due()} · DPA approved</span></p><div class="signature"><span>${en?'Master signature':'선장 서명'}<span class="signature-line" aria-hidden="true"></span></span><span>${en?'Date':'일자'}<span class="signature-line" aria-hidden="true"></span></span></div><p class="small muted mt">${en?'Preparation record only; does not replace an official PSC inspection. Translation reference: English source.':'공식 PSC 검사를 대체하지 않는 입항 준비 기록입니다. 번역 기준은 영어 원문입니다.'}</p><p class="small muted">시연용 모의 데이터 · 선박·IMO 가상 · 통계 출처 Tokyo MOU</p></article>`;}
function reportPage(){return heading('입항 준비 보고서','확인된 기록과 남은 증빙 상태를 함께 담았습니다.',tag('발행 완료','ok'))+`<div class="row between wrap mb report-toolbar"><div class="view-tabs"><button data-action="report-language" data-value="en" class="${S.reportLang==='en'?'active':''}">English</button><button data-action="report-language" data-value="ko" class="${S.reportLang==='ko'?'active':''}">한국어</button></div>${btn(icon('print')+' PDF 저장/인쇄','print','small')}</div><p class="arrival-history report-info">D-4 · 미응답 ${activeItems().length-6} → D-3 · ${activeItems().length-8}항목 수신 → D-2 · 전체 답변 완료</p>${reportContent()}<div class="sticky-actions">${btn(icon('download')+' CSV','csv')}${S.shared?notice('선장에게 공유됨 · 11/03 14:20','ok','check'):btn(icon('send')+' 선장에게 공유','share','primary')}</div><p class="report-info muted small">PDF 저장은 인쇄 창에서 선택합니다. 선장 공유는 이 브라우저의 선장 화면에 전달합니다.</p>`;}
function captain(){const s=stats();if(S.shared)return `<div class="row between mb"><h3>입항 준비 보고서</h3>${tag('도착','ok')}</div><p class="muted mb">${S.arrival} · ${S.port}</p>${btn(icon('file')+' 보고서 크게 보기','captain-report','primary')}<div class="phone-card"><p class="muted">점검 완료율</p><div class="huge">${s.percent}<span style="font-size:var(--f28)">%</span></div><p class="muted mt">지난 ISM 지적: 증빙 준비 중</p></div>`;return `<span class="eyebrow muted">입항 준비 현황</span><div class="huge mt">${s.percent}<span style="font-size:var(--f28)">%</span></div><p class="muted mt">전체 ${s.total}항목 중 ${s.answered}항목 응답<br>미응답 ${s.missing} · 시정 대기 ${s.open}</p><div class="mt">${progress(s.percent)}</div><div class="phone-card"><h3>담당 배정</h3><p class="muted mt">담당자가 없는 항목은 보고서에 반영할 수 없습니다.</p>${btn('담당자 변경','assign','wide mt','data-value="generator"')}</div>${S.report?btn('입항 준비 보고서 확인','captain-report','primary mt'):notice('사무실이 검토를 마치면 보고서가 도착합니다.','neutral','clock')}`;}
function fullNav(){return `<div class="filter-bar">${['선대','전체 점검','기록'].map(t=>`<button data-action="dashboard-tab" data-value="${t}" class="${dashboardTab===t?'active':''}">${t}</button>`).join('')}</div>`;}
function auditRecords(){return [...S.log,...Array.from({length:100},(_,i)=>({date:`2026-10-${String(25-Math.floor(i/5)%20).padStart(2,'0')}`,text:`${D.ships[i%3].name} · ${D.items[i%D.items.length].ko} · 점검 기록 ${String(100-i).padStart(3,'0')}`}))];}
function audit(){const history=auditRecords().filter(x=>(x.text+x.date).toLowerCase().includes(search.toLowerCase()));return heading('운항 점검 기록','선박·항목을 검색하고 기록을 내보내세요.',btn(icon('download')+' 기록 CSV','audit-csv','small'))+`<div class="search">${icon('search')}<input id="audit-search" type="search" aria-label="기록 검색" value="${esc(search)}" placeholder="선박명 또는 점검 항목 검색"></div><div class="list-header"><h3>기록 ${history.length}건</h3><span class="muted small">${auditPage} / ${Math.max(1,Math.ceil(history.length/10))} 페이지</span></div><div class="card">${history.slice((auditPage-1)*10,auditPage*10).map(x=>`<div class="audit-row"><div><strong>${esc(x.text)}</strong><p class="muted small">${x.date}</p></div>${tag('보관')}</div>`).join('')||'<div class="empty">검색 결과가 없습니다.</div>'}</div><div class="row between mt">${btn('이전','audit-prev','small',auditPage<=1?'disabled':'')}${btn('다음','audit-next','small',auditPage*10>=history.length?'disabled':'')}</div>`;}
function done(){return `<section class="card done-card">${icon('shield')}<p class="eyebrow muted">ONE VOYAGE, ONE RECORD</p><h1>입항 준비가<br>하나의 기록으로 연결됩니다.</h1><p class="muted">항차 등록 → 선내 점검 → 검토와 시정 → 지난 지적 증빙 → 입항 준비 보고서</p><div class="row" style="justify-content:center">${btn('처음부터 다시','reset','primary')}<a class="btn" href="full.html#scene-1">대시보드 전체 보기 ${icon('arrow')}</a></div><button class="btn ghost mt" data-action="sources">데이터 출처 보기</button></section>`;}
function openSheet(title,body){modalTrigger=document.activeElement;sheet.innerHTML=`<header class="sheet-head"><h2 id="sheet-title">${title}</h2><button class="iconbtn" data-action="close" aria-label="닫기">${icon('x')}</button></header><div class="sheet-body">${body}</div>`;if(!sheet.open)sheet.showModal();}
function closeSheet(){sheet.close();if(modalTrigger?.isConnected)modalTrigger.focus();}
function voyageSheet(){openSheet(S.generated?'항차 정보 변경':'다음 항차 등록',`<div class="row"><span class="task-icon">${icon('ship')}</span><div><strong>한바다스타 · IMO 9000001</strong><p class="small">Bulk carrier · 35,000 GT · 2012년 건조</p></div></div><form id="voyage-form" class="stack"><label for="port">다음 기항지<select id="port" name="port">${['중국 칭다오','중국 르자오','일본 지바'].map(p=>`<option ${p===S.port?'selected':''}>${p}</option>`).join('')}</select></label><label for="arrival">입항 예정일<input id="arrival" name="arrival" type="date" min="2026-10-20" max="2027-12-31" required value="${S.arrival}"></label><label for="voyage-language">선원 언어<select id="voyage-language" name="language">${[['idn','Bahasa Indonesia'],['en','English'],['vi','Tiếng Việt · 영어로 표시'],['tl','Filipino · 영어로 표시']].map(([v,l])=>`<option value="${v}" ${S.language===v?'selected':''}>${l}</option>`).join('')}</select></label>${notice('지난 PSC 2026.06.02 · 결함 3건 · 억류 없음<br>기국: 대한민국 (High) · 선급: 미입력')}<p class="small">입항일이 바뀌면 CIC 적용과 시정 기한도 함께 바뀝니다.</p><button class="btn primary wide" type="submit">${S.generated?'다시 계산하기':'체크리스트 만들기'} ${icon('arrow')}</button></form>`);}
function sourceSheet(){openSheet('통계와 자료 출처',`<p>제공된 FACTS.md의 공개 수치를 사용합니다. 선박·항차·답변은 가상 기록이며 실제 점검 예측치가 아닙니다.</p><div><h3>한국 기국선 · 2025</h3><p>점검 1,106회 · 결함 있는 점검 792회 (71.6%)<br>결함 2,638건 · 점검당 2.38건 · 억류 10척</p></div>${D.sources.map(s=>`<a class="source-link" href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a>`).join('')}<p class="small">항만당국 억류율: 중국 6.96%, 일본 2.52%, 호주 4.80%, 한국 5.44%, 싱가포르 8.52%.<br>벌크선 3년 평균 억류율 3.52%.</p><p class="small">CIC는 10개 번호 문항을 1a·1b 등 11개 세부 행으로 표시합니다. 이 자료의 번역은 전문 검수 전이며 영어 원문을 기준으로 확인합니다.</p>`);}
function helpSheet(){openSheet('도움말 · 개인정보',`<div><h3>한 항차의 사용 순서</h3><p>항차 등록 → 배로 보내기 → 선내 점검 → 검토·시정 → 보고서 발행. 선원 폰에서 오프라인 답변을 저장한 뒤 연결하면 사무실에 전달됩니다.</p></div><div><h3>사진과 개인정보</h3><p>선원 사진은 선박 설비만 찍고 얼굴·이름표는 담지 않습니다. 운영 설계상 보관 기간은 3년이며, 이 화면의 기록은 현재 브라우저에만 저장됩니다. 외부로 전송하지 않습니다.</p></div><div><h3>권한 없이 이용</h3><p>카메라·위치·알림 권한을 요청하지 않습니다. 사진 첨부는 준비된 설비 이미지를 사용하고, 알림은 앱 안에 표시합니다. PDF는 브라우저 인쇄에서 저장합니다.</p></div><div><h3>연결과 저장 문제</h3><p>느린 연결에서는 대기열을 유지합니다. 창을 닫기 전 저장 표시를 확인하세요. 기기 저장을 막은 브라우저에서는 CSV를 먼저 내보내세요. 파일로 연 full.html의 상태 공유는 브라우저별 file 저장 정책에 따라 다를 수 있습니다.</p></div><div><h3>운영 담당자 문의</h3><p>문의 내용을 기기 내 지원 기록으로 남깁니다. 현재는 외부 고객지원 시스템에 전달되지 않습니다.</p></div><form id="help-form" class="stack"><label>문의 내용<textarea name="message" required maxlength="500" placeholder="기록이 보이지 않는 항목이나 문의를 남겨 주세요."></textarea></label><button class="btn primary" type="submit">문의 기록 저장</button></form>${btn('기록 CSV 내보내기','csv')}`);}
function onboardSheet(){openSheet(tr('Hubungkan akun kapal','Connect vessel account'),`<div><h3>Budi · Chief Engineer</h3><p>${bilingual('Gunakan undangan kapal Anda. Tidak perlu mendaftar lagi.','Use your vessel invitation. No separate sign-up needed.')}</p></div><p>${bilingual('Foto peralatan saja, tanpa wajah. Data disimpan selama 3 tahun.','Equipment photos only, no faces. Records are retained for 3 years.')}</p><form id="onboard-form" class="stack"><label class="check-label"><input name="consent" type="checkbox" required>${bilingual('Saya menyetujui pengumpulan catatan pemeriksaan dan penyimpanan selama 3 tahun.','I agree to collection and 3-year retention of inspection records.')}</label><button class="btn primary" type="submit">${bilingual('Hubungkan','Connect')}</button></form>${btn(tr('Nanti','Later'),'close','ghost')}<p class="small">${bilingual('Tidak memerlukan izin kamera, lokasi, atau notifikasi.','No camera, location, or notification permissions required.')}</p>`);}
function evidenceSheet(id){const x=item(id);openSheet('왜 이 항목을 먼저 보나요?',`<div><h3>${x.ko}</h3><p>${x.en}</p></div>${x.top?`<div class="card"><span class="muted">2025 억류 관련 결함</span><div class="metric">${x.top}건</div><p>Tokyo MOU Annual Report 2025 · Table 15</p></div>`:''}<p>범주 ${x.category}: 결함 ${D.categories[x.category].count.toLocaleString()}건 (${D.categories[x.category].share}%).${x.previous?'<br>이 배의 지난 PSC 보고서에 같은 항목이 지적됐습니다.':''}${x.cic?`<br>CIC 질문 ${x.question} · 화물 고박 집중점검.`:''}</p><p>현재 준비 우선순위 점수: ${ranked().find(r=>r.id===id)?.score.toFixed(2)||'기간 외'}. 공식 NIR 위험도 점수와는 별도입니다.</p>${btn('전체 산식 확인','ranking-info')}${D.sources.map(s=>`<a class="source-link" href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a>`).join('')}`);}
function rankingSheet(){openSheet('준비 우선순위 산식',`<p>통계와 자기 선박 이력으로 점검 순서를 정하는 제품 규칙입니다. 항만별 개별 결함 확률이나 공식 Tokyo MOU 산식은 아닙니다.</p><div class="card"><code>범주 비중 × 1.3<br>+ 억류 다발이면 8<br>+ 억류 건수 ÷ 10 × (항만당국 억류율 ÷ 6.96)<br>+ 지난 지적이면 12<br>+ CIC 기간의 항목이면 18</code></div><p>중국 ${D.ports['중국'].value}% → 일본 ${D.ports['일본'].value}%로 바꾸면 억류 다발 항목의 상대 가중치가 달라집니다. 중국 안에서 기항지를 바꾸면 같은 당국 통계이므로 순위는 유지됩니다.</p><p>벌크선 3년 평균 억류율 3.52%는 선박 맥락으로 표시합니다. 모든 항목에 같은 값을 더해 순위를 바꾸는 것처럼 표시하지 않습니다.</p>${btn('공개 수치 출처','sources')}`);}
function csv(auditMode=false){const rows=auditMode?[['날짜','기록'],...auditRecords().map(x=>[x.date,x.text])]:[['선박','IMO','기항지','입항일','항목','결함코드','담당','답변','시정승인','사진','메모'],...activeItems().map(x=>['한바다스타','9000001',S.port,S.arrival,x.ko,D.codes[x.id]||'',owner(x),S.received[x.id]||'미응답',S.approved[x.id]?'승인':'',S.photos[x.id]?'첨부':'',S.notes[x.id]||''])];const cell=v=>`"${String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')}"`;const blob=new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=auditMode?'psc-audit.csv':'psc-hanbada-checklist.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV 기록을 내보냈습니다.');}
function changeAnswer(value){const x=crew()[crewIndex];S.answers[x.id]=value;if(!S.queue.includes(x.id))S.queue.push(x.id);delete S.approved[x.id];delete S.corrections[x.id];invalidate();if(!S.offline)sync();save();render();toast(S.offline?tr('Tersimpan di perangkat','Saved on device'):tr('Terkirim ke kantor','Sent to office'));}
function rejectSheet(){openSheet('사진 다시 요청',`<img class="retake-preview wide blurred" src="img/fire-pump.jpg" alt="압력계 눈금이 보이지 않는 사진"><form id="reject-form" class="stack"><fieldset class="reason-options"><legend>재촬영이 필요한 이유</legend><label><input type="radio" name="reason" value="blur" checked>압력계 숫자가 안 보임</label><label><input type="radio" name="reason" value="wrong">점검 대상과 다른 사진</label></fieldset><p>기관장에게 인도네시아어·영어로 알림을 전달합니다.</p><button class="btn primary" type="submit">재촬영 요청 보내기</button></form>`);}
function photoSheet(){const photoId=crew()[crewIndex].id;openSheet(tr('Foto peralatan','Equipment photo'),`<img class="retake-preview wide" src="${equipmentImage(photoId)}" alt="Prepared vessel equipment image"><p>${bilingual('Lampirkan foto peralatan yang tersedia. Izin kamera tidak diperlukan.','Attach the prepared equipment image. No camera permission required.')}</p>${notice(bilingual('Model pengiriman: 4.1MB → 280KB. Foto lokal sudah dioptimalkan.','Transfer model: 4.1MB → 280KB. Local photo is already optimized.'))}<div class="row">${btn(tr('Gunakan foto ini','Use this photo'),'use-photo','primary grow')}${btn(tr('Batal','Cancel'),'close')}</div>`);}
function notifySheet(phone=false){openSheet(phone?tr('Notifikasi','Notifications'):'알림',`${S.rejected?notice(phone?bilingual('Foto perlu diambil ulang: angka manometer tidak terlihat.','Photo retake needed: gauge numbers are not visible.'):'압력계 숫자가 보이지 않아 재촬영이 필요합니다.','warn','camera'):''}${S.ordered?notice(phone?bilingual(`Perbaiki 2 item sebelum ${due()}.`,`Correct 2 items by ${due()}.`):`미비 2건 · 시정 기한 ${due()}`,'neutral','clock'):''}${S.evidenceRequested?notice(phone?'PMS maintenance record · Work photos · Internal audit record':'15150 · PMS 정비기록·작업 사진·내부심사 기록 요청','neutral','file'):''}${S.shared?notice(phone?bilingual('Laporan kesiapan pelabuhan tersedia.','Port Readiness Report is ready.'):'입항 준비 보고서가 도착했습니다.','ok','check'):''}${!S.rejected&&!S.ordered&&!S.shared&&!S.evidenceRequested?`<div class="empty">${phone?tr('Belum ada notifikasi.','No notifications yet.'):'새 알림이 없습니다.'}</div>`:''}`);}
function handleAction(action,el){const value=el.dataset.value;switch(action){case 'exception-missing':missingExample=!missingExample;view='office';render();window.scrollTo(0,0);break;case 'next':navigate(scene+1);break;case 'nav':navigate(Number(value));break;case 'view':view=value;render();break;case 'voyage':voyageSheet();break;case 'close':closeSheet();break;case 'onboard':onboardSheet();break;case 'sources':sourceSheet();break;case 'help':helpSheet();break;case 'ranking-info':rankingSheet();break;case 'evidence':evidenceSheet(value);break;case 'notifications':notifySheet();break;case 'phone-notices':notifySheet(true);break;case 'dispatch':if(!S.generated)return;if(stats().unassigned){toast('담당자 미지정 항목을 먼저 배정해 주세요.');break;}S.dispatched=true;log('체크리스트 선내 배포');save();render();toast('기관부 6 · 갑판부 4 · 선장 2 우선 항목 배정 · 전체 목록 배포 완료');break;case 'fast':fastAnswers();if(!S.offline)sync();save();render();toast('보낼 답 6건 · 사진 3장 — 기기에 저장했습니다.');break;case 'connection':S.offline=!S.offline;if(!S.offline){sync();toast('보냄 ✓ 사진 4.1MB → 280KB (전송 모델)');}save();render();break;case 'answer':changeAnswer(value);break;case 'photo':photoSheet();break;case 'use-photo':photo(crew()[crewIndex].id);save();closeSheet();render();toast(tr('Foto tersimpan','Photo saved'));break;case 'remove-photo':delete S.photos[crew()[crewIndex].id];save();render();toast(tr('Foto dihapus. Anda dapat melampirkannya lagi.','Photo removed. You can attach it again.'));break;case 'undo':{const id=crew()[crewIndex].id;delete S.answers[id];delete S.received[id];S.queue=S.queue.filter(x=>x!==id);invalidate();save();render();toast(tr('Jawaban dibatalkan','Answer undone'));break;}case 'crew-prev':crewIndex=Math.max(0,crewIndex-1);render();break;case 'crew-next':if(!S.answers[crew()[crewIndex].id]){toast(tr('Pilih Ya atau Tidak','Choose Yes or No'));break;}if(crewIndex<5){crewIndex++;render();}else{toast(S.queue.length?tr(`${S.queue.length} jawaban menunggu koneksi`,`${S.queue.length} answers waiting for connection`):tr('Semua jawaban terkirim','All answers sent'));}break;case 'filter':filter=value;render();break;case 'clear-filter':filter='전체';search='';render();break;case 'reject':rejectSheet();break;case 'order':openSheet('시정 지시 보내기',`<p>기관장에게 아래 2건의 시정을 요청합니다.</p><div class="card">소화펌프 압력 시험<br>비상발전기 자동 기동</div>${notice(`시정 기한 ${due()} · 입항 2일 전`,'warn','clock')}${btn('기관장에게 보내기','confirm-order','primary')}`);break;case 'confirm-order':S.ordered=true;log('미비 2건 시정 지시 · 기한 '+due());save();closeSheet();render();toast('기관장에게 시정 지시 2건을 보냈습니다.');break;case 'analyze':loading='analysis';reportRows=0;render();for(let i=1;i<=3;i++)setTimeout(()=>{reportRows=i;if(i===3){S.analyzed=true;loading='';log('부산 PSC Form B 3건 구조화 확인');save();}render();},i*220);break;case 'request-evidence':S.evidenceRequested=true;log('15150 PMS·작업사진·내부심사 기록 요청');save();render();toast('증빙 3개 요청을 기관장에게 보냈습니다.');break;case 'correct':if(S.offline){if(!S.correctionQueue.includes(value))S.correctionQueue.push(value);photo(value);invalidate();save();render();toast(tr('Foto perbaikan tersimpan. Menunggu koneksi.','Correction photo saved. Waiting for connection.'));break;}S.corrections[value]=true;photo(value);if(value==='fire-pump')S.retaken=true;invalidate();log(item(value).ko+' 시정 사진 도착');save();render();toast(tr('Foto perbaikan terkirim ke kantor','Correction photo sent to office'));break;case 'approve':if(!S.corrections[value])return;S.approved[value]=true;invalidate();log(item(value).ko+' DPA 승인');save();render();toast('시정 증빙을 승인했습니다.');break;case 'receive-others':receiveOthers();log('갑판부·선장 점검 답변 수신');save();render();toast('남은 점검 답변을 수신했습니다.');break;case 'issue':if(blockers().length){toast(blockers().join(' · '));break;}S.report=true;S.reportLang='en';log('입항 준비 보고서 발행');save();render();window.scrollTo(0,0);break;case 'report-language':S.reportLang=value;save();render();break;case 'print':if(!S.report)return;view='office';render();window.print();break;case 'share':if(!S.report)return;S.shared=true;log('선장 화면에 보고서 공유');save();render();toast('선장에게 보고서를 공유했습니다. 선장 탭에서 확인하세요.');break;case 'captain-report':if(!S.report){toast('사무실에서 보고서를 준비 중입니다.');break;}view='office';if(scene!==5)navigate(5);else render();break;case 'csv':csv();break;case 'audit-csv':csv(true);break;case 'dashboard-tab':dashboardTab=value;search='';auditPage=1;render();break;case 'audit-prev':auditPage=Math.max(1,auditPage-1);render();break;case 'audit-next':auditPage++;render();break;case 'assign':{const x=item(value);openSheet('담당자 배정',`<h3>${x.ko}</h3><form id="assign-form" data-id="${x.id}" class="stack"><label>담당<select name="owner">${['기관장','1항사','선장',''].map(v=>`<option value="${v}" ${owner(x)===v?'selected':''}>${v||'미지정'}</option>`).join('')}</select></label><button class="btn primary" type="submit">배정 저장</button></form>`);break;}case 'ship-detail':{const x=D.ships[Number(value)];openSheet(x.name,`<p>${x.imo} · Bulk carrier · 35,000 GT<br>${x.arrival} 입항 예정 · 대한민국 기국</p><div class="metric">${value==='1'?83:100}%</div>${progress(value==='1'?83:100,value==='2')}${notice(value==='1'?'점검 진행 중 · 검토 대기 1건':'입항 준비 보고서 확인 완료','neutral')}<p>이 선박의 운항 요약입니다. 항차 편집은 한바다스타에서 진행할 수 있습니다.</p>`);break;}case 'reset':openSheet('현재 항차 기록 초기화',`<p>이 브라우저에 저장된 점검·시정·보고서를 초기화합니다. 필요한 기록은 먼저 CSV로 내려받으세요.</p>${btn('CSV 내보내기','csv')}<div class="row">${btn('취소','close','grow')}${btn('초기화하고 시작','confirm-reset','primary grow')}</div>`);break;case 'confirm-reset':S=fresh();save();closeSheet();dashboardTab='선대';if(location.hash==='#scene-1')route();else navigate(1);toast('새 항차 준비를 시작합니다.');break;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)handleAction(el.dataset.action,el);});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,fd=new FormData(f);if(f.id==='voyage-form'){const before=ranked().map(x=>x.id);const wasGenerated=S.generated;S.port=fd.get('port');S.arrival=fd.get('arrival');S.language=fd.get('language');const after=ranked().map(x=>x.id),changed=after.filter((id,i)=>before[i]!==id).length+before.filter(id=>!after.includes(id)).length;S.rankChanges=Object.fromEntries(after.map((id,i)=>[id,before.includes(id)?before.indexOf(id)-i:0]));S.rankChangedCount=wasGenerated?changed:0;S.generated=true;invalidate();closeSheet();loading='generate';render();setTimeout(()=>{loading='';log(`항차 ${S.port} ${S.arrival} 등록/변경`);save();render();toast(wasGenerated?`순위가 바뀐 항목 ${changed}개 · ${isCic()?'CIC 포함':'CIC 제외'}`:'우선순위 체크리스트를 만들었습니다.');},600);}else if(f.id==='onboard-form'){S.onboard=true;save();closeSheet();render();toast(tr('Akun kapal terhubung','Vessel account connected'));}else if(f.id==='reject-form'){S.rejected=true;S.rejectReason=fd.get('reason');S.retaken=false;invalidate();log('압력계 사진 재촬영 요청');save();closeSheet();render();toast('Foto perlu diambil ulang · 재촬영 요청을 보냈습니다.');}else if(f.id==='assign-form'){S.owners[f.dataset.id]=fd.get('owner');invalidate();log(item(f.dataset.id).ko+' 담당 변경');save();closeSheet();render();toast('담당 배정을 저장했습니다.');}else if(f.id==='help-form'){log('지원 문의: '+fd.get('message'));save();closeSheet();toast('문의 내용을 이 기기에 저장했습니다. 외부로 전송하지 않았습니다.');}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.change==='language'){S.language=el.value;save();if(sheet.open&&sheet.querySelector('#onboard-form')){closeSheet();onboardSheet();}else {render();document.getElementById('crew-language')?.focus();}}if(el.dataset.change==='note'){S.notes[crew()[crewIndex].id]=el.value;save();}if(el.id==='report-upload')checkFile(el.files[0]);});
document.addEventListener('input',e=>{if(e.target.id==='review-search'||e.target.id==='audit-search'){const id=e.target.id,pos=e.target.selectionStart;search=e.target.value;auditPage=1;render();const input=document.getElementById(id);input.focus();try{input.setSelectionRange(pos,pos);}catch{}}if(e.target.id==='crew-note'){S.notes[crew()[crewIndex].id]=e.target.value;save();}});
function checkFile(file){if(!file)return;const valid=file.name.toLowerCase().endsWith('.pdf')&&file.size<10*1024*1024;openSheet(valid?'보고서 파일 확인':'파일을 확인해 주세요',valid?`<p>${esc(file.name)} · ${Math.ceil(file.size/1024)}KB</p>${notice('현재 자동 PDF 판독은 연결되지 않았습니다. 준비된 6월 부산항 보고서로 구조화 결과를 확인할 수 있습니다.','warn')}<button class="btn primary" data-action="load-sample">준비된 보고서 불러오기</button>`:notice('10MB 이하의 PDF 파일만 선택할 수 있습니다. 파일 형식과 크기를 확인하고 다시 선택해 주세요.','bad','alert'));}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="load-sample"]')){closeSheet();handleAction('analyze',document.createElement('button'));}});
document.addEventListener('dragover',e=>{const zone=e.target.closest('#dropzone');if(zone){e.preventDefault();zone.classList.add('drag');}});document.addEventListener('dragleave',e=>e.target.closest('#dropzone')?.classList.remove('drag'));document.addEventListener('drop',e=>{const zone=e.target.closest('#dropzone');if(zone){e.preventDefault();zone.classList.remove('drag');checkFile(e.dataTransfer.files[0]);}});
sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet();}});
window.addEventListener('hashchange',route);window.addEventListener('pageshow',()=>{S=restore();render();});window.addEventListener('storage',e=>{if(e.key===KEY){S=restore();render();}});
window.addEventListener('offline',()=>{S.offline=true;save();render();toast('오프라인 · 답변은 이 기기에 저장됩니다.');});window.addEventListener('online',()=>{S.offline=false;sync();render();toast('다시 연결되어 대기 답변을 보냈습니다.');});
route();
})();
